        return False
    if not isinstance(messages, tuple):
        return False
    data = bytes(data)
    if len(data) < _MULTIPROOF_HEADER_BYTES:
        return False
    if data[:8] != _MULTIPROOF_MAGIC:
        return False
    if data[8] != _MULTIPROOF_VERSION:
        return False
