        messages = (b"a", b"b", b"c")
        blob = make_proof(signer, messages)
        self.assertTrue(multiproof_verify(messages, blob))
        self.assertTrue(
            multiproof_verify_bound(messages, blob, public_key=signer.public_key)
        )


